            Planet.SATURN -> listOf("New loans", "Optional fees", "Interest you can avoid")
            Planet.URANUS -> listOf("Renewing a stale contract", "Old route fees", "Penalties you can contest")
            Planet.NEPTUNE -> listOf("Storm-season sailings", "Vague invoices", "Wine for the table")
            Planet.PLUTO -> listOf("Disputed claims", "Hidden charges", "Contested will payments")
        }

        AncientCulture.ROME -> when (body) {
            Planet.SUN -> listOf("Boasting at dinner", "Arriving late", "Bad company")
            Planet.MOON -> listOf("Domestic rows", "Late revels", "Neglecting home")
            Planet.MERCURY -> listOf("Signing unread papers", "Long speeches", "Repeating hearsay")
            Planet.VENUS -> listOf("Public scandal", "Rivalry over a suitor", "Lavish banquets")
            Planet.MARS -> listOf("Quarrels with officers", "Reckless charges", "Street fights")
            Planet.JUPITER -> listOf("Buying votes", "Overreaching claims", "Showing off wealth")
            Planet.SATURN -> listOf("Running up debts", "New spending", "Extravagant dinners")
            Planet.URANUS -> listOf("Factional feuds", "Rigid orders", "Refusing change")
            Planet.NEPTUNE -> listOf("Too much wine", "Spreading rumors", "Idle festivals")
            Planet.PLUTO -> listOf("Contesting wills", "Old family feuds", "Secret deals")
        }
    }
}

/** The culture's own pair of column heads for the Do and Don't lists. */
fun permissionPair(culture: AncientCulture): Pair<String, String> = when (culture) {
    AncientCulture.EGYPT -> "OFFER" to "WITHHOLD"
    AncientCulture.GREECE -> "ASK" to "DO NOT ASK"
    AncientCulture.CANAAN -> "BRING" to "HOLD BACK"
    AncientCulture.CARTHAGE -> "PAY" to "DEFER"
    AncientCulture.ROME -> "PROCEED" to "REFRAIN"
}

/**
 * The day page's dive deeper, from web/src/data/diveDeeperBanks.ts: per
 * culture, four group titles and four quiet lines in the group order (work
 * and substance, home and kin, words and errands, the inner court), and the
 * concrete line's frame. DiveDeeperComposer reads them.
 */
object DiveDeeperBanks {
    /** The group's name and its concern in plain words. */
    fun title(culture: AncientCulture, group: Int): String = when (culture) {
        AncientCulture.EGYPT -> listOf("The Granary: your work and your rations", "The House of the Ka: your home and your forebears", "The Ferry: your letters and your crossings", "The Sealed Shrine: what you keep to yourself")
        AncientCulture.GREECE -> listOf("The Agora: your silver and your trade", "The Oikos: your hearth and your kin", "The Herm: your messages and your roads", "The Adyton: the questions you ask alone")
        AncientCulture.CANAAN -> listOf("The Threshing Floor: your labor and your yield", "The Father's House: your kin and your birthright", "The Gate: your word and your witnesses", "The Tent of El: your prayers and your vows")
        AncientCulture.CARTHAGE -> listOf("The Counting House: your wages and your weights", "The Courtyard: your household and your heirs", "The Harbor: your contracts and your ships", "The Precinct: the vows you still owe")
        AncientCulture.ROME -> listOf("The Forum: your standing and your coin", "The Domus: your family and your Lares", "The Via: your dispatches and your errands", "The Templum: the signs you take in private")
    }[group]

    /** What a group says when no figure touches it. */
    fun quiet(culture: AncientCulture, group: Int): String = when (culture) {
        AncientCulture.EGYPT -> listOf("No figure reaches the granary today. Draw your ration and work the row you were given.", "The house of the ka stands apart from the day's figures. Fill the ancestors' lamp and eat at home.", "Nothing waits at the landing today. Send what you owe by the usual boat.", "The sealed shrine stays shut, and no figure knocks. Say the morning hymn and leave it there.")
        AncientCulture.GREECE -> listOf("The agora is empty of figures today. Sell at yesterday's price and count the silver once.", "No figure crosses the threshold of the oikos today. Bank the hearth and eat with your household.", "The herm stands alone at the crossroads today. Send your messages by the road you always take.", "The adyton is silent today. Keep your question for a day when the tripod speaks.")
        AncientCulture.CANAAN -> listOf("No matter comes to the threshing floor today. Thresh the sheaves you have and sweep the floor at dusk.", "The father's house has no case before the council today. Break bread with your kin and settle nothing.", "No one is called to the gate today. Greet the elders and go about your errands.", "The tent of El stays closed today. Say the evening prayer and go to sleep.")
        AncientCulture.CARTHAGE -> listOf("The counting house posts no new entry today. Pay the wages on the list and lock the strongbox.", "Nothing is charged to the courtyard today. Check the household book and close it.", "No figure touches the harbor today. Let the ships keep their posted sailings.", "The precinct asks nothing new of you today. Pay what you vowed, when you vowed it, and no more.")
        AncientCulture.ROME -> listOf("The forum shows no sign for you today. Receive your clients and keep your appointments.", "The domus is left out of the day's auspices. Feed the Lares and keep the household to its routine.", "The road is clear today. Send the dispatches you planned.", "The templum gives no sign today. Leave the auspices alone and keep your vows.")
    }[group]

    /** What a group says when every figure touching it is read above. Slot: {group}, that group's name. */
    fun shared(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "The same weight that sits on {group} reaches here too, and the scale reads it once."
        AncientCulture.GREECE -> "The answer given at {group} is the one this place hears too."
        AncientCulture.CANAAN -> "The matter heard at {group} is the same matter heard here."
        AncientCulture.CARTHAGE -> "The entry posted under {group} is charged here as well, and it is not entered twice."
        AncientCulture.ROME -> "The sign read in {group} falls here as well, and the augur does not take it twice."
    }

    /** The paragraph's last line. Slot: {thing}, a manifestation. */
    fun concrete(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "Reckon on {thing}."
        AncientCulture.GREECE -> "Look for {thing}."
        AncientCulture.CANAAN -> "Be ready for {thing}."
        AncientCulture.CARTHAGE -> "Enter it in the daybook: {thing}."
        AncientCulture.ROME -> "Watch for {thing}."
    }
}

/**
 * What each god brings before its institution: a short noun phrase in the
 * culture's own nouns. The week's ingress line reads it into its frame.
 */
fun deityCharge(culture: AncientCulture, body: Planet): String = when (culture) {
    AncientCulture.EGYPT -> when (body) {
        Planet.SUN -> "the day's own course"
        Planet.MOON -> "the count of the months"
        Planet.MERCURY -> "the storm off the red land"
        Planet.VENUS -> "the gathering of the limbs"
        Planet.MARS -> "the falcon's harpoon"
        Planet.JUPITER -> "the hidden king's hand"
        Planet.SATURN -> "the weight of the ground itself"
        Planet.URANUS -> "the gap of five days outside the year"
        Planet.NEPTUNE -> "the dark water under everything"
        Planet.PLUTO -> "the green grain of the Duat"
    }

    AncientCulture.GREECE -> when (body) {
        Planet.SUN -> "the eye that misses no deed"
        Planet.MOON -> "the light borrowed from Helios"
        Planet.MERCURY -> "the word carried through the door"
        Planet.VENUS -> "the girdle that turns every head"
        Planet.MARS -> "the slaughter looking for a field"
        Planet.JUPITER -> "the nod that shakes Olympus"
        Planet.SATURN -> "the sickle's one question"
        Planet.URANUS -> "the sky unthroned in one stroke"
        Planet.NEPTUNE -> "the ground that will not hold still"
        Planet.PLUTO -> "the silver under the earth"
    }

    AncientCulture.CANAAN -> when (body) {
        Planet.SUN -> "the herald's message brought down from the sky"
        Planet.MOON -> "the bride price paid by moonlight"
        Planet.MERCURY -> "the mace forged for Baal's hand"
        Planet.VENUS -> "the armed morning star"
        Planet.MARS -> "the arrow of plague in flight"
        Planet.JUPITER -> "the rain that decides the harvest"
        Planet.SATURN -> "the word from the tent at the source of the rivers"
        Planet.URANUS -> "the offering owed to Heaven itself"
        Planet.NEPTUNE -> "the sea's claim to the throne"
        Planet.PLUTO -> "the open gullet of death"
    }

    AncientCulture.CARTHAGE -> when (body) {
        Planet.SUN -> "the Tyrian sun over the new city"
        Planet.MOON -> "the dedication cut into the stele beneath the crescent"
        Planet.MERCURY -> "the guide's landfall on a foreign shore"
        Planet.VENUS -> "the war fleet launched under the Lady of the Sea"
        Planet.MARS -> "the champion's yearly tithe to Tyre"
        Planet.JUPITER -> "the horned lord of the gods"
        Planet.SATURN -> "the whole of the Ancient One's due"
        Planet.URANUS -> "the foremost name in the city's oath"
        Planet.NEPTUNE -> "the partner of every hull out of Carthage"
        Planet.PLUTO -> "the debt that outlives the debtor"
    }

    AncientCulture.ROME -> when (body) {
        Planet.SUN -> "the unconquered light"
        Planet.MOON -> "the chariot of the moon"
        Planet.MERCURY -> "the bargain struck in the market"
        Planet.VENUS -> "the marriage of two houses"
        Planet.MARS -> "the shield of the Salii"
        Planet.JUPITER -> "the thunderbolt from the Alban Mount"
        Planet.SATURN -> "the treasury at the Capitol's foot"
        Planet.URANUS -> "the canopy over every army"
        Planet.NEPTUNE -> "the failing spring at the Neptunalia"
        Planet.PLUTO -> "the altar buried at the Tarentum"
    }
}

/** The verb an ingress line uses: "{deity} {verb} the {sign image}." */
fun ingressVerb(culture: AncientCulture): String = when (culture) {
    AncientCulture.EGYPT -> "is ferried into"
    AncientCulture.GREECE -> "goes on to the shrine of"
    AncientCulture.CANAAN -> "comes before"
    AncientCulture.CARTHAGE -> "makes port in"
    AncientCulture.ROME -> "enters the augur's boundary of"
}

/**
 * The ruling on an ingress, taking the moving body's charge. A body that has
 * crossed into a new sign has not been ruled on there yet, and each of these
 * says that in its own institution's terms.
 */
fun ingressFrame(culture: AncientCulture, c: String): String = when (culture) {
    AncientCulture.EGYPT -> "The priest of the hours on the temple roof watches the sign's decans rise and reads ${c} in them."
    AncientCulture.GREECE -> "The priests there begin the sacrifice for ${c}."
    AncientCulture.CANAAN -> "${cap(c)} moves to the house of another god, where no envoy has announced it."
    AncientCulture.CARTHAGE -> "The clerk carries ${c} onto a fresh sheet of the ledger and rules off the last one."
    AncientCulture.ROME -> "The auspices taken for ${c} lapse at that boundary, and the college takes new ones beyond it."
}
